// NOTE: Badge wrapper for navbar links that display metadata (version, blog posts, etc.)
'use client';

import Link from 'next/link';

import { LazyMotion, domAnimation, m } from 'motion/react';

import { Badge } from '@/components/ui/badge';
import { EASE } from '@/lib/animation-config';
import { cn } from '@/lib/utils';

interface NavbarBadgeLinkProps {
  href: string;
  label: string;
  icon?: React.ReactNode;
  metadata: string; // version number or blog post title
  active?: boolean;
  className?: string;
  borderColor?: string; // Custom border color (e.g., 'border-black' for floating navbar)
  textColor?: string; // Custom text color for metadata and icon (e.g., 'text-white' for hero, 'text-black' for floating)
}

/**
 * NavbarBadgeLink Component
 *
 * A specialized link component that displays as a pill badge with metadata.
 * Used in the navbar for Changelog (with version) and Blog (with latest post).
 *
 * Features:
 * - Combines shadcn Badge with Next.js Link
 * - Displays label | metadata with pipe separator
 * - Smooth hover animations matching navbar style
 * - Active state highlighting
 * - Respects navbar variant styling through className prop
 *
 * @example
 * <NavbarBadgeLink
 *   href="/changelog"
 *   label="Changelog"
 *   metadata="v0.1.0"
 *   active={pathname === '/changelog'}
 * />
 */
export function NavbarBadgeLink({
  href,
  label,
  metadata,
  icon,
  active = false,
  className,
  borderColor,
  textColor,
}: NavbarBadgeLinkProps) {
  return (
    <LazyMotion features={domAnimation}>
      <Link href={href}>
        <m.div
          whileHover={{
            scale: 1.05,
            transition: {
              duration: 0.2,
              ease: EASE.expOut,
            },
          }}
          whileTap={{ scale: 0.97 }}
        >
          <Badge
            variant={'outline'}
            className={cn(
              'h-9 cursor-pointer gap-2 px-1 py-2 text-lg font-semibold transition-all',
              active && 'bg-accent text-accent-foreground',
              borderColor, // Apply custom border color if provided
              className
            )}
          >
            <span className="rounded-4xl bg-[#222] px-2 text-white">
              {label}
            </span>
            <span className={cn('font-normal', textColor)}>{metadata}</span>
            {icon && (
              <span className={cn('flex items-center', textColor)}>{icon}</span>
            )}
          </Badge>
        </m.div>
      </Link>
    </LazyMotion>
  );
}
